CREATE OR REPLACE FUNCTION public.audit_admin_profile_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_actor uuid := auth.uid();
  v_email text;
begin
  if v_actor is null or public.is_admin() is not true or new is not distinct from old then
    return new;
  end if;
  select email into v_email from public.profiles where id = v_actor;
  insert into public.audit_logs (actor_id, actor_email, actor_role, action, target_type, target_id, details)
  values (v_actor, v_email, 'admin', 'user_updated', 'user', old.id::text, '{}'::jsonb);
  if new.role is distinct from old.role then
    insert into public.audit_logs (actor_id, actor_email, actor_role, action, target_type, target_id, details)
    values (v_actor, v_email, 'admin', 'user_role_changed', 'user', old.id::text,
      jsonb_build_object('old_role', old.role, 'new_role', new.role));
  end if;
  if new.status is distinct from old.status then
    insert into public.audit_logs (actor_id, actor_email, actor_role, action, target_type, target_id, details)
    values (v_actor, v_email, 'admin', 'user_status_changed', 'user', old.id::text,
      jsonb_build_object('old_status', old.status, 'new_status', new.status));
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.guard_profiles_role_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.status is distinct from old.status
     and public.is_admin() is not true
     and not (auth.uid() is null and current_setting('role') in ('none', 'postgres', 'service_role')) then
    raise exception 'Unauthorized: only administrators can modify account status.';
  end if;

  if (new.role is distinct from old.role or new.provider_type is distinct from old.provider_type)
     and (public.is_admin() or pg_trigger_depth() > 1) is not true then
    raise exception 'Unauthorized: only administrators can modify role or provider_type directly.';
  end if;
  return new;
end;
$function$
